SELECT id, launch_date, supplier_id, RANK() OVER (ORDER BY stock_qty NULLS FIRST) stock_qty_rank, ROUND(price / SUM(price) OVER (PARTITION BY brand), 4) price_share, ROW_NUMBER() OVER w_grp event_seq, FIRST_VALUE(brand, TRUE) OVER (PARTITION BY DATE_TRUNC('WEEK', launch_date), category ORDER BY stock_qty, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) first_known_brand, CORR(price, cost) OVER w_part corr_price_cost FROM products WINDOW w_grp AS (ORDER BY stock_qty, id), w_part AS (PARTITION BY category)
